#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <fcntl.h>

#define CHEMIN "/tmp/canal_entier"

int main(void) {
    if (mkfifo(CHEMIN, 0666) == -1 && errno != EEXIST) {
        perror("mkfifo"); exit(EXIT_FAILURE);
    }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        int fd = open(CHEMIN, O_WRONLY);
        if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }
        int valeur = 2025;
        write(fd, &valeur, sizeof(valeur));
        close(fd);
        exit(EXIT_SUCCESS);
    } else {
        int fd = open(CHEMIN, O_RDONLY);
        if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }
        int recu;
        read(fd, &recu, sizeof(recu));
        close(fd);
        wait(NULL);
        printf("entier recu : %d\n", recu);
        unlink(CHEMIN);
    }
    return 0;
}

