#include <pthread.h>
#include <stdio.h>

#define NB_OUVRIERS 6

int termines = 0;
long total = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  tous_finis = PTHREAD_COND_INITIALIZER;

void *ouvrier(void *arg) {
    long id = (long) arg;
    pthread_mutex_lock(&mutex);
    total += id;
    termines++;
    pthread_cond_signal(&tous_finis);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void *collecteur(void *arg) {
    long *resultat = (long *) arg;
    pthread_mutex_lock(&mutex);
    while (termines < NB_OUVRIERS)
        pthread_cond_wait(&tous_finis, &mutex);
    *resultat = total;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main(void) {
    pthread_t ouvr[NB_OUVRIERS];
    pthread_t coll;
    long resultat = 0;

    pthread_create(&coll, NULL, collecteur, &resultat);

    for (long i = 1; i <= NB_OUVRIERS; i++)
        pthread_create(&ouvr[i - 1], NULL, ouvrier, (void *) i);

    for (int i = 0; i < NB_OUVRIERS; i++)
        pthread_join(ouvr[i], NULL);
    pthread_join(coll, NULL);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&tous_finis);
    printf("total = %ld\n", resultat);
    return 0;
}

