#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <fcntl.h>

#define FIFO_REQ "/tmp/req_longueur"
#define FIFO_REP "/tmp/rep_longueur"

int main(void) {
    if (mkfifo(FIFO_REQ, 0666) == -1 && errno != EEXIST) { perror("mkfifo"); exit(EXIT_FAILURE); }
    if (mkfifo(FIFO_REP, 0666) == -1 && errno != EEXIST) { perror("mkfifo"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        /* SERVEUR : lit une chaine, renvoie sa longueur */
        int fd = open(FIFO_REQ, O_RDONLY);
        if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }
        char mot[256];
        ssize_t n = read(fd, mot, sizeof(mot) - 1);
        if (n < 0) n = 0;
        mot[n] = '\0';
        close(fd);
        int longueur = (int) strlen(mot);
        int fr = open(FIFO_REP, O_WRONLY);
        if (fr == -1) { perror("open"); exit(EXIT_FAILURE); }
        write(fr, &longueur, sizeof(longueur));
        close(fr);
        exit(EXIT_SUCCESS);
    } else {
        /* CLIENT : envoie "systeme", lit la longueur renvoyee */
        int fd = open(FIFO_REQ, O_WRONLY);
        if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }
        const char *mot = "systeme";
        write(fd, mot, strlen(mot));
        close(fd);
        int fr = open(FIFO_REP, O_RDONLY);
        if (fr == -1) { perror("open"); exit(EXIT_FAILURE); }
        int longueur;
        read(fr, &longueur, sizeof(longueur));
        close(fr);
        printf("longueur : %d\n", longueur);
        wait(NULL);
        unlink(FIFO_REQ);
        unlink(FIFO_REP);
    }
    return 0;
}
